changeSet.sql:
ALTER TABLE nexus.catalog_links NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_row           RECORD;
    v_total_count   BIGINT;
    v_export_count  INTEGER := 0;
    v_deleted_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO v_total_count
    FROM nexus.catalog_links l
    WHERE NOT EXISTS (
        SELECT 1 FROM nexus.catalog_documents d
         WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.from_tumbler
    ) OR NOT EXISTS (
        SELECT 1 FROM nexus.catalog_documents d
         WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.to_tumbler
    );

    RAISE NOTICE 'RDR-194 P1 catalog_links-FK remediation (nexus-tk070.p1): % dangling catalog_links row(s) found (from_tumbler or to_tumbler has no matching nexus.catalog_documents row); exporting up to 200 below before delete', v_total_count;

    FOR v_row IN
        SELECT l.tenant_id, l.from_tumbler, l.to_tumbler, l.link_type
          FROM nexus.catalog_links l
         WHERE NOT EXISTS (
             SELECT 1 FROM nexus.catalog_documents d
              WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.from_tumbler
         ) OR NOT EXISTS (
             SELECT 1 FROM nexus.catalog_documents d
              WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.to_tumbler
         )
         ORDER BY l.tenant_id, l.from_tumbler, l.to_tumbler, l.link_type
         LIMIT 200
    LOOP
        v_export_count := v_export_count + 1;
        RAISE NOTICE 'RDR-194 P1 dangling catalog_links row %/% (of % total): tenant_id=%, from_tumbler=%, to_tumbler=%, link_type=%',
            v_export_count, LEAST(v_total_count, 200), v_total_count,
            v_row.tenant_id, v_row.from_tumbler, v_row.to_tumbler, v_row.link_type;
    END LOOP;

    DELETE FROM nexus.catalog_links l
    WHERE NOT EXISTS (
        SELECT 1 FROM nexus.catalog_documents d
         WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.from_tumbler
    ) OR NOT EXISTS (
        SELECT 1 FROM nexus.catalog_documents d
         WHERE d.tenant_id = l.tenant_id AND d.tumbler = l.to_tumbler
    );
    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'RDR-194 P1 catalog_links-FK remediation (nexus-tk070.p1): deleted % dangling catalog_links row(s) with no matching nexus.catalog_documents endpoint', v_deleted_count;
END $$;

ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_links FORCE ROW LEVEL SECURITY;

ANALYZE nexus.catalog_links;
